package com.tanidikvar.api.answer.service;
import com.tanidikvar.api.answer.dto.AnswerLikeResponse;import com.tanidikvar.api.answer.repository.AnswerLikeRepository;import com.tanidikvar.api.auth.service.AccountAccessService;import com.tanidikvar.api.common.error.DomainException;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AnswerLikeService{private final AnswerLikeRepository likes;private final AccountAccessService accounts;public AnswerLikeService(AnswerLikeRepository likes,AccountAccessService accounts){this.likes=likes;this.accounts=accounts;}@Transactional public AnswerLikeResponse set(UUID actor,UUID answer,boolean liked){accounts.lockActive(actor);if(!likes.visible(answer))throw new DomainException(404,"NOT_FOUND","Yorum bulunamadı.");likes.set(answer,actor,liked);return new AnswerLikeResponse(liked,likes.count(answer));}@Transactional public AnswerLikeResponse get(UUID actor,UUID answer){accounts.lockActive(actor);if(!likes.visible(answer))throw new DomainException(404,"NOT_FOUND","Yorum bulunamadı.");return new AnswerLikeResponse(likes.liked(answer,actor),likes.count(answer));}}
